DROP TABLE IF EXISTS `account`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `account` (
  `id` int NOT NULL AUTO_INCREMENT,
  `account_no` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '账号',
  `customer_id` int NOT NULL COMMENT '客户ID',
  `account_type` enum('储蓄','支票','信用卡','理财') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '账户类型',
  `open_date` date DEFAULT NULL COMMENT '开户日期',
  `balance` decimal(15,2) DEFAULT '0.00' COMMENT '当前余额',
  `avg_monthly_balance` decimal(15,2) DEFAULT '0.00' COMMENT '月均余额',
  `total_deposit` decimal(15,2) DEFAULT '0.00' COMMENT '累计存款',
  `total_withdraw` decimal(15,2) DEFAULT '0.00' COMMENT '累计取款',
  `num_transactions` int DEFAULT '0' COMMENT '交易笔数',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否活跃',
  `last_transaction_date` date DEFAULT NULL COMMENT '最后交易日期',
  PRIMARY KEY (`id`),
  UNIQUE KEY `account_no` (`account_no`),
  KEY `customer_id` (`customer_id`),
  CONSTRAINT `account_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=256 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='账户信息表';
