/*!40000 ALTER TABLE `churn_predict_result` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `customer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `customer` (
  `id` int NOT NULL AUTO_INCREMENT,
  `customer_no` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户编号',
  `name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓名',
  `gender` enum('男','女') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '性别',
  `age` int DEFAULT NULL COMMENT '年龄',
  `education` enum('高中','大专','本科','硕士','博士') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学历',
  `occupation` enum('公务员','事业单位','企业员工','个体经营','自由职业','退休','学生','其他') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职业',
  `income_level` enum('低','中低','中','中高','高') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收入水平',
  `marital_status` enum('未婚','已婚','离异') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '婚姻状况',
  `residence_years` decimal(4,1) DEFAULT NULL COMMENT '居住年限',
  `property_status` enum('无房','有房(有贷)','有房(无贷)') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '房产状况',
  `credit_history_months` int DEFAULT NULL COMMENT '信用历史月数',
  `num_credit_cards` int DEFAULT NULL COMMENT '信用卡数量',
  `has_overdue` tinyint(1) DEFAULT '0' COMMENT '是否有逾期记录',
  `churn_label` tinyint DEFAULT '0' COMMENT '流失标签 0=留存 1=流失',
  `risk_level` enum('低风险','中风险','高风险') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '风险等级',
  `segment_label` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户分群标签',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `customer_no` (`customer_no`)
) ENGINE=InnoDB AUTO_INCREMENT=112 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='客户信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `customer` WRITE;
