UNLOCK TABLES;
DROP TABLE IF EXISTS `loan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `loan` (
  `id` int NOT NULL AUTO_INCREMENT,
  `loan_no` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '贷款编号',
  `customer_id` int NOT NULL COMMENT '客户ID',
  `loan_type` enum('个人消费贷','房贷','车贷','经营贷','信用贷') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '贷款类型',
  `loan_amount` decimal(15,2) NOT NULL COMMENT '贷款金额',
  `interest_rate` decimal(5,4) NOT NULL COMMENT '年利率',
  `loan_term_months` int NOT NULL COMMENT '贷款期限(月)',
  `monthly_payment` decimal(15,2) DEFAULT NULL COMMENT '月供金额',
  `outstanding_balance` decimal(15,2) DEFAULT NULL COMMENT '剩余本金',
  `loan_status` enum('审批中','已放款','还款中','已结清','逾期','坏账') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '贷款状态',
  `overdue_months` int DEFAULT '0' COMMENT '逾期月数',
  `collateral_type` enum('无','房产','车辆','存单','其他') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '担保方式',
  `default_label` tinyint DEFAULT '0' COMMENT '违约标签 0=正常 1=违约',
  `credit_score` int DEFAULT NULL COMMENT '信用评分',
  `application_date` date DEFAULT NULL COMMENT '申请日期',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `loan_no` (`loan_no`),
  KEY `customer_id` (`customer_id`),
  CONSTRAINT `loan_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=64 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='贷款信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `loan` WRITE;
