CREATE TABLE `orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `customer_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户名称',
  `product_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品名称',
  `amount` decimal(12,2) NOT NULL COMMENT '订单金额',
  `quantity` int NOT NULL COMMENT '数量',
  `order_date` date NOT NULL COMMENT '订单日期',
  `region` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '区域(华东/华南/华北/西南)',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'pending' COMMENT '状态(pending/completed/cancelled)',
  `salesperson_id` int DEFAULT NULL COMMENT '销售人员ID',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单表';
