/*!40000 ALTER TABLE `salary_regression_test` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `transaction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `transaction` (
  `id` int NOT NULL AUTO_INCREMENT,
  `transaction_no` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '交易流水号',
  `account_id` int NOT NULL COMMENT '账户ID',
  `transaction_type` enum('存款','取款','转账','消费','理财','贷款还款','利息') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '交易类型',
  `amount` decimal(15,2) NOT NULL COMMENT '交易金额',
  `balance_after` decimal(15,2) DEFAULT NULL COMMENT '交易后余额',
  `channel` enum('柜台','ATM','网银','手机银行','第三方') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '渠道',
  `counterparty` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '交易对手',
  `remark` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `is_fraud` tinyint(1) DEFAULT '0' COMMENT '是否欺诈交易',
  `transaction_date` datetime NOT NULL COMMENT '交易时间',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `transaction_no` (`transaction_no`),
  KEY `account_id` (`account_id`),
  CONSTRAINT `transaction_ibfk_1` FOREIGN KEY (`account_id`) REFERENCES `account` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4096 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='交易流水表';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `transaction` WRITE;
/*!40000 ALTER TABLE `transaction` DISABLE KEYS */;
